import type { Publication } from './publication-manifest';

export const nov08ResearchPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "research", "slug": "how-much-of-an-assistants-week-goes-to-unplanned-requests", "title": "How much of an assistant's week goes to unplanned requests?", "description": "A method for logging interruptions, separating necessary responsiveness from avoidable churn, and turning the result into a capacity decision.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/how-much-of-an-assistants-week-goes-to-unplanned-requests-hero.webp", "thumbnail": "/thumbnails/november-8/how-much-of-an-assistants-week-goes-to-unplanned-requests.webp", "heroAlt": "How much of an assistant's week goes to unplanned requests?", "topic": "unplanned request load", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/run-a-monthly-one-on-one-with-a-remote-assistant-using-queue-evidence", "label": "Read the remote one-on-one guide"}, "sources": [{"label": "U.S. Bureau of Labor Statistics, American Time Use Survey", "href": "https://www.bls.gov/tus/"}, {"label": "O*NET OnLine, Secretaries and Administrative Assistants", "href": "https://www.onetonline.org/link/summary/43-6014.00"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how much of a virtual assistant's working week goes to requests that were not on the plan. The unit is a task that enters after the day or week has been scheduled and displaces planned work. The scope covers recurring administrative and support roles where the assistant serves one client or a small client group. The review does not estimate a universal percentage, because the mix of planned and unplanned work varies by role, season, and client.", "The question matters because unplanned work is usually invisible in a task list. A completed queue can look healthy while the assistant absorbed a stream of interruptions that pushed the real priorities to the evening. The review treats that hidden load as a capacity and design issue rather than a personal failing. The goal is a measurement a manager can reproduce.", "Two definitions keep the count honest. Planned work is a task that appeared on the approved queue or schedule before the day began, while unplanned work is a request that arrived later and required action that day. A request that arrived late but waited until the next day is deferred work, not necessarily an interruption. The distinction prevents the log from counting the same task twice.", "A role with a fixed daily queue behaves differently from a role that covers a shared inbox. Measure the queue role and the inbox role separately before comparing them. The mix of channels changes the interruption pattern more than the job title does. A buyer should not generalize from one role to another."]}, {"id": "why-it-is-hard-to-measure", "heading": "Why unplanned work is hard to measure", "paragraphs": ["Most task systems record the work that was completed, not the work that arrived and was refused or delayed. A request handled in a chat thread may never appear in the queue at all. That gap makes the planned list look cleaner than the real week. A useful measure has to start from the channels where requests actually appear.", "Assistants also absorb interruptions without labeling them as work. A quick question, a file resend, or a clarification call can take four minutes each and still break concentration for twenty. The cost is not only the minutes but the restart time that follows. A log that records only duration will understate the effect on planned tasks.", "Cross-channel work is the hardest to see because each tool keeps its own history. A request may start in email, move to chat, and finish in a task system. The log should record the source that started the work and the channel where it was completed. Otherwise the same request appears twice or disappears between the tools."]}, {"id": "what-the-evidence-can-show", "heading": "What time-use and work-context evidence can show", "paragraphs": ["The American Time Use Survey provides a national picture of how people spend time across work and non-work activities. It can show that work is fragmented and that some tasks cluster at particular times, but it does not measure one assistant's queue. The survey is useful for framing the question, not for setting a target. A buyer should read it as context rather than as a benchmark for an individual.", "O*NET work-context data describes the conditions of an occupation, including the importance of interruptions and the pace of work. That description supports the claim that responsiveness is part of many administrative roles. It still cannot say how many interruptions a specific client creates. The individual estimate must come from the assistant's own log.", "Use public evidence to justify why the measurement is worth doing, then replace it with local data for any decision. A manager who quotes a national average to demand a specific capacity change will usually lose the argument. A manager who shows four weeks of local logs can make a targeted fix that the assistant recognizes as fair. State the source and the limit beside every external number."]}, {"id": "build-an-interruption-log", "heading": "Build an interruption log from real weeks", "paragraphs": ["Ask the assistant to log every request that arrives outside the planned queue for four normal weeks. Record the time, the requester, the channel, the action taken, the time spent, and whether planned work moved. Keep the log to a simple form so it does not become another interruption. Four weeks is usually enough to see a pattern without creating logging fatigue.", "Include the requests that were handled in under two minutes, because they are the easiest to miss and the most likely to break focus. Group them by requester and channel at the end of the week. The pattern often shows that one client or one chat channel produces most of the churn. That finding is more actionable than a single total.", "Keep the log in a tool the assistant already uses so it does not become a second job. A form linked from the task queue is better than a separate spreadsheet that has to be remembered. Review the first week together and fix the fields that are hard to complete. The log should take seconds per entry, not minutes."]}, {"id": "separate-responsiveness-from-churn", "heading": "Separate necessary responsiveness from avoidable churn", "paragraphs": ["Not every interruption is waste. A customer escalation or a time-sensitive approval may be exactly the work the role exists to absorb. Mark each logged request as necessary, preventable, or duplicate. Necessary requests belong in the capacity plan, while preventable ones point to a missing brief or a broken tool. The labels turn a count into a decision.", "Preventable churn usually has a small set of causes, such as an unclear form, a missing status update, or a requester who does not know where to ask. Fixing one cause can remove a recurring category of requests. The goal is not to make the assistant unreachable. The goal is to keep the interruptions that add value and remove the ones that only repeat information."]}, {"id": "turn-the-finding-into-capacity", "heading": "Turn the finding into a capacity decision", "paragraphs": ["Compare the unplanned hours with the planned hours and the available hours for the same weeks. If unplanned work consumes a fifth of the week, then the queue was planned against a week that did not exist. Adjust the plan, the staffing, or the service promise rather than asking the assistant to absorb the gap silently. Capacity math should include the interruption allowance.", "Decide which requests need a faster channel and which can wait for the daily queue. Publish the response expectation for each channel so requesters know where urgency belongs. A named channel for urgent work reduces the tendency to mark everything urgent. The plan should also say who covers the urgent channel when the assistant is away.", "Recheck the interruption allowance after the change rather than treating the first estimate as permanent. A new client or a seasonal peak can shift the mix within a few weeks. Compare the same measures and adjust one variable at a time. A capacity plan that is reviewed on a schedule stays useful after the original project ends."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a measurement method rather than a study of a specific provider or team. The public sources are national or occupational descriptions, and their definitions may not match a given role. The local log is self-reported unless it is paired with system timestamps. A manager should state those limits when presenting the result.", "Interruption logging can change behavior while it is happening. Assistants may record more carefully or requesters may route work differently because they know the log exists. Treat the first week as a settling period and compare later weeks with the same method. Do not use the log as a performance score, because that would encourage under-reporting."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Confirm the definition of planned and unplanned work, the logging period, and the channels included. Check that the log captures short requests as well as long ones. Review the pattern by requester and channel rather than only by total. Agree on one cause to fix and one capacity change to test.", "Set a review date and compare the same measures. Ask the assistant whether the change reduced the load or merely moved it. Keep the log until the next review and then retire it if the question is answered. A measurement that never ends becomes a burden that the team learns to game."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-a-redaction-checklist-catch-before-a-client-file-is-shared", "title": "What does a redaction checklist catch before a client file is shared?", "description": "A review of direct and contextual identifiers, hidden metadata, and scanned evidence, with a checklist a buyer can test on real files.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/what-does-a-redaction-checklist-catch-before-a-client-file-is-shared-hero.webp", "thumbnail": "/thumbnails/november-8/what-does-a-redaction-checklist-catch-before-a-client-file-is-shared.webp", "heroAlt": "What does a redaction checklist catch before a client file is shared?", "topic": "redaction review", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/build-a-document-redaction-checklist-before-an-assistant-shares-a-file", "label": "Read the document redaction guide"}, "sources": [{"label": "HHS Office for Civil Rights, Guidance on De-identification", "href": "https://www.hhs.gov/hipaa/for-professionals/privacy/special-topics/de-identification/index.html"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "FTC, Disposing of Your Records", "href": "https://www.ftc.gov/business-guidance/resources/disposing-your-records"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what a redaction checklist can catch before a client file leaves the organization. The unit is a document, image, or export prepared for an external audience. The scope covers routine business files rather than court-ordered disclosures or regulated clinical records, which may require a specialist. The review does not certify a tool or a provider, and it does not replace the client's legal or compliance review.", "The question matters because most redaction failures are not dramatic. A name left in a footer, an author field in the file properties, or a tracked change can expose more than the visible page. A checklist is valuable when it targets those layers rather than only the obvious text. The test is whether a second reader can still identify a person from the released copy.", "The review separates the removal of data from the proof that removal happened. A file can look clean and still carry the original in a hidden sheet or a revision history. A release record that names the reviewer, the version, and the test performed is part of the control. Without that record, the organization cannot show what it checked."]}, {"id": "deletion-is-not-redaction", "heading": "Deletion is not redaction", "paragraphs": ["Deleting a row or covering text with a shape changes what appears on the page, not necessarily what the file contains. Underlying cells, comments, and previous versions may keep the original value. A true redaction removes the content from the file and leaves no recoverable copy in the released format. The difference is easy to test by reopening the export and searching for the removed term.", "The same rule applies to images. A black rectangle placed over a screenshot may sit on a separate layer that a recipient can move or delete. Flatten the image and confirm the covered pixels are gone before sharing. If the tool cannot flatten the content, rebuild the image from a cropped or re-captured source. A visual cover is not a control."]}, {"id": "direct-and-contextual-identifiers", "heading": "Direct and contextual identifiers", "paragraphs": ["Direct identifiers name a person or an account, such as a full name, address, phone number, email, or government identifier. Contextual identifiers work in combination, such as a rare job title, a small town, a date, and a unique event. A checklist that stops at the direct list will miss the combination that actually identifies someone. The reviewer has to read for both.", "HHS guidance on de-identification makes a similar distinction between removing specified identifiers and reducing the risk that the remaining data can be used to identify a person. The guidance is written for protected health information, but the reasoning transfers to other sensitive files. A buyer can use it to frame questions without treating it as a universal legal standard. Read the current guidance and confirm which definition applies to the data.", "Replace removed identifiers with a consistent label rather than a blank. A label such as Client A or Site 2 preserves the logic of the document while hiding the identity. Use the same label throughout the document and keep the mapping in a separate restricted record. An inconsistent label can itself reveal which entries belong together."]}, {"id": "metadata-and-hidden-layers", "heading": "Metadata and hidden layers", "paragraphs": ["File properties can include the author, the organization, the original path, and the date of creation. Tracked changes can show every deletion and the name of the person who made it. Comments and speaker notes can carry candid detail that never appears in the body. Each of these layers needs an explicit check before release.", "Spreadsheets add hidden rows, hidden columns, named ranges, and pivot caches that may retain source data. Presentations add off-slide objects and notes. PDFs add attachments, form data, and incremental updates. A checklist should name the export path for each file type rather than assuming that save as PDF removes the extras.", "NIST SP 800-53 provides a control catalog for protecting information across its lifecycle, including media sanitization and access enforcement. It does not prescribe a single redaction procedure for business documents. It does support the principle that removal must be verifiable and that residual copies need an owner. Use it as a framework for the control, not as a step-by-step guide.", "Check the file's revision history and any linked source that the document references. A shared file may point to a cloud document that still contains the original text. The link itself can be a path back to the restricted version. Remove the link or replace it with a plain reference before release."]}, {"id": "scanned-pages-and-images", "heading": "Scanned pages and image evidence", "paragraphs": ["A scanned page may be an image with no searchable text, which makes automated checks unreliable. Run optical character recognition on a copy and search the result for the removal terms. Then inspect the image itself for handwriting, stamps, signatures, and background detail that the text layer missed. The two checks catch different failures.", "Check the edges of the scan for a fax header, a patient label, or a case number that the crop did not remove. Signatures and initials can identify a person even when the typed name is gone. If the signature is not needed, remove it rather than covering it. The same rule applies to photographs of whiteboards and screens.", "Some scans contain multiple pages in one file, and a clean first page can hide a header on the next. Check every page and every attachment before release. If the tool merges pages, confirm that the merged file is the one that was reviewed. A page-level review is slower than a file-level glance and far more reliable."]}, {"id": "a-testable-checklist", "heading": "A testable checklist", "paragraphs": ["Write the checklist as observable steps rather than general advice. Each step should name the action, the tool, and the evidence that proves it happened. For example, export to PDF, search for the removal list, and record the zero-result search. A checklist that cannot be tested becomes a ritual that people sign without doing.", "Include a second-reader step and a release record. The second reader opens the final file without the removal list and describes who could be identified. The release record stores the reviewer, the version, the audience, and the test result. Together they show that the organization checked the result rather than only the process.", "Set a stop rule for files that contain data the reviewer cannot classify. A file with clinical, legal, or credential content should go to the specialist owner rather than through the routine checklist. The assistant should know the stop rule before starting the review. A checklist that encourages guessing on sensitive files creates more risk than it removes.", "Keep the checklist short enough to complete in one sitting. A long form invites a partial review followed by a signature. Group the steps by the tool or the file type so the reviewer does not jump between tasks. The order should match the way the file is actually prepared."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review draws on federal guidance and a control framework rather than a controlled study of redaction outcomes. The sources describe legal and security expectations, not the error rate of a particular team. The checklist is a practical control that a buyer can test, not a guarantee of anonymity. A file that passes the checklist may still carry risk in combination with other data.", "Redaction also depends on the receiving context. A file that is safe for one audience may be unsafe for another when combined with public records. The reviewer should state the assumed audience and the limits of the check. Where legal, clinical, or regulatory duties apply, obtain advice for the actual document and jurisdiction."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Confirm the audience, the purpose, and the exact file that will be released. List the direct and contextual identifiers and decide which will be removed, replaced, or retained under an exception. Check metadata, hidden layers, and embedded objects for each file type. Test the export and record the search result.", "Ask a second reader to try to identify a person from the released copy. Record the reviewer, the version, and the date in the release log. Set a retention and disposal rule for the original and the released copy. Re-run the check after any edit, even a small one."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "can-a-shared-credential-vault-shorten-access-handoff-delay", "title": "Can a shared credential vault shorten access handoff delay?", "description": "Where access handoff delay comes from, what a vault can and cannot fix, and how to measure the change without weakening accountability.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/can-a-shared-credential-vault-shorten-access-handoff-delay-hero.webp", "thumbnail": "/thumbnails/november-8/can-a-shared-credential-vault-shorten-access-handoff-delay.webp", "heroAlt": "Can a shared credential vault shorten access handoff delay?", "topic": "credential handoff", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/manage-a-shared-credential-vault-for-a-distributed-assistant-team", "label": "Read the credential vault management guide"}, "sources": [{"label": "NIST SP 800-63B, Digital Identity Guidelines", "href": "https://pages.nist.gov/800-63-4/sp800-63b.html"}, {"label": "CISA Cyber Essentials", "href": "https://www.cisa.gov/cyber-essentials"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks whether a shared credential vault can shorten the time it takes to hand access from one assistant to another. The unit is a task-level access change, such as adding a backup to an inbox or moving a client tool to a new owner. The scope covers small teams that share client accounts under a provider relationship. The review does not assume that a vault is the right control for every account, because some systems support named users and should not be shared at all.", "The question matters because access delay is often invisible until a task is already late. A backup who cannot open the tool cannot cover the queue, and the client sees a missed response rather than an access problem. A vault may reduce the time spent finding and sharing a secret, but it can also add approval steps. The net effect has to be measured rather than assumed.", "The review separates three times that are often merged. Request time is the interval between the need and the request, approval time is the interval between the request and the decision, and provisioning time is the interval between the decision and working access. A vault mainly affects the third, and sometimes the first, while approval time depends on people and policy. Reporting one combined number hides the part that needs repair."]}, {"id": "where-delay-comes-from", "heading": "Where handoff delay comes from", "paragraphs": ["Delay usually starts before the credential is shared. The requester may not know who owns the account, the approver may be away, or the client may need to create the account first. A vault cannot fix a missing owner or an unresponsive approver. Measure each interval so the fix targets the part that is actually slow.", "The second source is the handoff method itself. A secret sent through chat, stored in a spreadsheet, or written in a ticket creates cleanup work and a risk of stale copies. The recipient may also need a second factor that lives on someone else's phone. A vault can centralize the secret and the second factor, but only if the enrollment path is designed.", "The third source is verification. A new user may have the credential but not the permission, the group, or the client's approval. Time spent discovering that the login works but the mailbox is not delegated is still handoff delay. The process should define working access as the ability to complete the task, not the ability to sign in."]}, {"id": "what-a-vault-changes", "heading": "What a vault changes and what it does not", "paragraphs": ["A vault changes where the secret lives and who can see it. It can remove the need to send a password through chat and can revoke access in one place. It can also record views and changes, which makes the handoff auditable. Those are real gains when the old process depended on memory and personal stores.", "A vault does not create a client account, grant a permission inside the client's tool, or approve a request. It also does not remove the need for a named user where the client requires one. A team that buys a vault and keeps the same approval bottleneck should not expect a large change in total handoff time. The tool supports a process rather than replacing it.", "A vault can also lengthen the first handoff if the enrollment is unfamiliar. A new assistant may need help installing the app, enrolling a second factor, and finding the right group. Build that help into the first day rather than leaving it to a chat message. The time saved on later handoffs should be compared with the time added at onboarding."]}, {"id": "design-rules", "heading": "Design rules that preserve accountability", "paragraphs": ["Use named vault accounts for each person and task groups for access. A shared vault login hides who viewed a secret and makes revocation blunt. If a client tool forces a shared login, record the individual behind each session through a separate log or ticket reference. Accountability should survive the sharing.", "Set the approval rule before the first request. A low-risk tool may need only the team lead, while a financial or administrative account may need the client. Publish the rule and the expected response time. A vault that stores the secret but leaves the approval path undefined will still stall at the same point.", "NIST SP 800-63B describes digital identity practices, including authenticator requirements and recovery. It reinforces that a shared secret with no individual identity is a weak control. CISA's cyber guidance similarly emphasizes strong authentication and least privilege. Use both to justify the design, then test the actual client tools against it."]}, {"id": "recovery-and-break-glass", "heading": "Recovery and break-glass paths", "paragraphs": ["Design a recovery path for a lost second factor or a locked account. Name who can approve a temporary credential and how long it remains valid. Record the approval and the revocation in the same place as the access change. A break-glass path without a time limit becomes a permanent backdoor.", "Keep at least two administrators who can perform recovery, and test the path before an emergency. A single administrator is a bottleneck during leave and a risk during departure. The test should use a low-risk account and should confirm that the normal path is restored afterward. The result belongs in the access record.", "Do not let a recovery path bypass the client's own security requirements. If the client requires a named user and a second factor, a shared workaround may violate the contract even when it is convenient. Escalate the conflict rather than resolving it quietly. The provider should document the exception and its expiry.", "Store the break-glass procedure where the on-call person can reach it without the vault itself. A recovery guide that lives inside the system it is meant to recover is not available during an outage. Keep a printed or offline copy under the administrator's control. Review the copy when the procedure changes so it does not go stale."]}, {"id": "measuring-the-change", "heading": "Measuring the change without inflating it", "paragraphs": ["Measure the three intervals before and after the vault: request, approval, and provisioning. Use the same task types and the same definition of working access. A drop in provisioning time is meaningful only if the total time also falls. Report the median and the slowest cases rather than only the average, because the slow cases are what the client notices.", "Track the number of access changes that required a manual cleanup, such as a secret left in chat or a session that survived a password change. Also track the removals completed on the last day. A vault that speeds up grants but slows removals has moved the risk rather than reduced it. The measure should cover the full lifecycle.", "Compare a small before-and-after sample and state the limits. The team may change other things at the same time, and the sample may be too small for a confident estimate. Use the result to decide whether to expand the vault, not to claim a universal improvement. A provider that reports the method invites a fair review."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review is based on identity and security guidance rather than a timed study of provider handoffs. The sources define good practice, not the performance of a specific team. The measurement method is a template that a buyer can apply to its own records. It does not establish that a vault will shorten delay in every environment.", "Access also depends on the client's systems, which the provider may not control. A client that creates accounts slowly will dominate the total time regardless of the vault. The review treats that dependency as part of the finding rather than an excuse. The buyer should separate provider-controlled and client-controlled intervals before setting a target."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Map the request, approval, and provisioning intervals for one recurring access change. Identify which interval the provider controls and which the client controls. Confirm that the vault uses named users, task groups, strong authentication, and an audit log. Test the recovery path and the removal path, not only the grant.", "Measure the full lifecycle before and after the change, including cleanup and last-day removal. Compare the slowest cases and the exceptions. Record the result and the limits in the access review. Expand the vault only where the evidence shows a real gain without weakening accountability."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-do-booked-itineraries-change-before-departure", "title": "How often do booked itineraries change before departure?", "description": "What public aviation data can and cannot show about itinerary change, why tight connections fail, and how to build a change-tolerant trip.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/how-often-do-booked-itineraries-change-before-departure-hero.webp", "thumbnail": "/thumbnails/november-8/how-often-do-booked-itineraries-change-before-departure.webp", "heroAlt": "How often do booked itineraries change before departure?", "topic": "itinerary change", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/build-a-travel-brief-a-virtual-assistant-can-book-from", "label": "Read the travel brief guide"}, "sources": [{"label": "Bureau of Transportation Statistics, Airline On-Time Performance", "href": "https://www.bts.gov/topics/airlines-and-airports/airline-on-time-performance-and-causes-of-flight-delays"}, {"label": "U.S. Department of Transportation, Aviation Consumer Protection", "href": "https://www.transportation.gov/airconsumer"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often a booked itinerary changes before departure and what a buyer should do with that information. The unit is a change that affects the traveler's arrival, departure, or connection, whether the airline initiated it or the traveler requested it. The scope covers commercial air travel booked for business support. The review does not estimate a single change rate for all routes, because schedule stability varies by airline, airport, and season.", "The question matters because a travel plan is often treated as final once the confirmation arrives. In practice, airlines adjust schedules months ahead, and a connection that looked safe at booking can become impossible later. A support process that never rechecks the itinerary leaves the traveler to discover the change at check-in. The useful measure is not only how often changes happen but how much notice the traveler receives.", "The review separates airline-initiated schedule changes from traveler-initiated changes. The first is a service event that the provider should monitor, while the second is a decision that the brief should govern. Mixing the two in one statistic hides the part the assistant can control. A buyer can then ask for the right kind of evidence."]}, {"id": "what-public-data-measures", "heading": "What public aviation data measures", "paragraphs": ["The Bureau of Transportation Statistics publishes on-time performance and causes of delay for domestic U.S. flights. Those tables describe departures and arrivals against schedule, including cancellations and delay categories. They do not directly measure how often an itinerary was changed before departure. A delay on the day of travel is a different event from a schedule change made weeks earlier.", "The Department of Transportation's aviation consumer resources describe passenger rights and complaint routes for delays, cancellations, and tarmac events. They are useful for understanding what a traveler is owed and where to escalate. They do not provide a change-rate benchmark for a specific route. A buyer should read them as a rights framework rather than a planning statistic.", "Public data can still support a planning decision. A route with a history of delay at a connecting airport should be treated as less stable, even if the exact change rate is unknown. The buyer can combine the public pattern with the airline's own schedule history and the traveler's tolerance for risk. The result is a probability-informed plan rather than a false certainty.", "Check the reporting period and the airport pair before using a table. A national on-time rate can hide a route that performs much worse, and a good month can hide a seasonal pattern. Read the notes on cancellations and diversions as well as delays. The definitions matter when the number is used to justify a booking rule."]}, {"id": "schedule-versus-passenger-change", "heading": "Schedule change versus passenger change", "paragraphs": ["An airline schedule change can move a flight by minutes or by hours, and a small change can break a connection that was already tight. The traveler may receive an email, a text, or no notice at all, depending on the channel on the booking. A provider that checks the itinerary on a schedule catches the change before the traveler does. A provider that waits for the airline's message may learn too late.", "A passenger-initiated change is a decision, not a disruption. It may follow a meeting change, a family issue, or a preference. The travel brief should define who can authorize a change and how the cost is approved. Separating the two categories helps the assistant decide whether to monitor, negotiate, or ask."]}, {"id": "the-cost-of-tight-connections", "heading": "The hidden cost of tight connections", "paragraphs": ["A tight connection saves time on paper and costs time when the first flight is late. The minimum connection time published by an airport is a floor, not a promise, and it may not account for a terminal change or a security recheck. A traveler with a 45-minute connection and a checked bag carries more risk than the same traveler with no bag and a known gate. The brief should state the risk the traveler will accept.", "The cost of a missed connection includes the rebooking queue, the hotel, the missed meeting, and the recovery time the next day. Those costs usually exceed the fare difference between a tight itinerary and a safer one. A comparison that shows only the ticket price hides the expected cost of disruption. The assistant should show both when presenting options.", "Add the cost of a late arrival at the destination, not only the cost at the connection. A traveler who lands after the meeting has lost the fare and the opportunity. For a critical trip, the value of arriving the night before can exceed the hotel cost. The brief should state which commitments justify that choice."]}, {"id": "build-a-change-tolerant-itinerary", "heading": "Build a change-tolerant itinerary", "paragraphs": ["Prefer a connection that leaves a buffer beyond the airport minimum, especially on the last flight of the day. If the trip must arrive by a fixed time, choose an earlier flight or a different airport rather than relying on a tight transfer. Ask whether a direct route exists even if it costs more, because fewer segments mean fewer failure points. The best itinerary is the one that still works after one delay.", "Book the traveler on a single ticket where possible so the airline owns the rebooking when a connection fails. Separate tickets can be cheaper, but the traveler carries the risk of a missed connection. Record the trade-off in the brief and let the traveler decide. The assistant should not choose a separate-ticket itinerary without an explicit instruction.", "Check the itinerary again at a fixed interval before departure, such as two weeks, three days, and the day before. Put the check on the task queue so it does not depend on memory. If a change appears, compare the new arrival with the traveler's fixed appointments before accepting it. A recheck is cheap compared with a rescue at the airport."]}, {"id": "what-to-ask-a-provider", "heading": "What to ask a travel support provider", "paragraphs": ["Ask how the provider monitors schedule changes and how quickly it notifies the traveler. Request the channel, the interval, and the person responsible. A provider that only forwards airline emails is not monitoring. A provider that reviews the itinerary on a schedule can explain what it does when a change breaks a connection.", "Ask for the change policy in writing, including who may approve a rebooking and the cost limit. Request a recent example of a disruption and how it was handled, with client details removed. Compare the answer with the traveler's own tolerance for risk. A provider should be able to describe the escalation path without inventing a case.", "Ask how the provider records the traveler's preferences and whether those records are updated after each trip. A preference file that never changes becomes a source of repeated mistakes. Request the retention and access rules for passport and frequent-flyer data. Travel support handles sensitive identity documents, so the data-handling answer belongs in the review."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review uses public aviation performance and consumer-protection sources rather than a proprietary itinerary dataset. The public tables describe on-time performance and delay causes, not the rate of pre-departure schedule changes. The planning guidance is therefore a risk-management method, not a statistical prediction. A buyer should not quote a specific change rate without a source that measures it.", "Route stability also changes with seasons, airline schedules, and airport construction. A pattern observed last year may not hold next year. The review recommends monitoring the actual booking rather than relying on a historical average. Where a trip carries a critical commitment, the traveler should build in a recovery plan as well as a buffer."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Name the fixed appointments and the latest acceptable arrival for each. Compare at least two itineraries on total travel time and disruption risk, not only fare. Check the connection buffer against the airport minimum and the terminal layout. Confirm whether the booking is on one ticket and who owns the rebooking.", "Put itinerary rechecks on the task queue at fixed intervals. Define who monitors changes and how the traveler is notified. Set the approval limit and the change policy in writing. Review the trip afterward and record which assumption failed, if any."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-a-service-catalog-clarify-about-assistant-scope-disputes", "title": "What does a service catalog clarify about assistant scope disputes?", "description": "How inclusions, exclusions, response promises, and change control reduce disputes about what an assistant was hired to do.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/what-does-a-service-catalog-clarify-about-assistant-scope-disputes-hero.webp", "thumbnail": "/thumbnails/november-8/what-does-a-service-catalog-clarify-about-assistant-scope-disputes.webp", "heroAlt": "What does a service catalog clarify about assistant scope disputes?", "topic": "scope clarity", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/write-a-client-facing-service-catalog-for-assistant-tasks", "label": "Read the service catalog guide"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "FTC truth in advertising", "href": "https://www.ftc.gov/business-guidance/resources/truth-advertising"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what a client-facing service catalog clarifies about disputes over an assistant's scope. The unit is a disagreement about whether a task, volume, or response time was included in the service. The scope covers recurring assistant and support roles sold to a business client. The review does not address employment classification, pricing strategy, or the legal interpretation of a contract, which require separate advice.", "The question matters because many scope disputes are not caused by bad faith. The client and the provider often hold different pictures of the service because the sales conversation, the contract, and the daily request channel use different language. A catalog can align those pictures if it describes the work in observable terms. It cannot fix a relationship where one side deliberately hides the boundary.", "The review treats the catalog as an operating document rather than a brochure. Its test is whether a client can read an entry and predict what will happen to a real request. A catalog that passes that test reduces the number of conversations about whether something is included. It also gives the provider a defensible basis for saying no. Keep the test in mind when writing each entry."]}, {"id": "why-disputes-start-early", "heading": "Why disputes start before the invoice", "paragraphs": ["A scope dispute often begins with an ambiguous request that the assistant tries to help with. The client sees a helpful response and assumes the task is now part of the service. The provider later sees the work as an exception that should be billed or declined. The conflict is built into the first interaction, long before the invoice arrives.", "The request channel makes the problem worse when it accepts work in any format. A chat message that says can you also handle this creates an implied commitment. A catalog that names the intake fields and the included work gives the assistant a neutral way to redirect the request. The boundary is easier to hold when it is visible before the work starts.", "SBA guidance on hiring and managing employees emphasizes clear expectations and written terms, while the FTC's truth-in-advertising guidance addresses the accuracy of promises made to customers. Neither source prescribes a service catalog, but both support the principle that the published description should match the delivered service. A catalog is one way to make that match checkable. Read the current guidance rather than relying on a summary."]}, {"id": "included-excluded-assumed", "heading": "Included, excluded, and assumed work", "paragraphs": ["A strong catalog has three lists for each service: what is included, what is excluded, and what is assumed about the client's environment. Included work names the tasks and the output. Excluded work names the tasks that require a different owner or a separate agreement. Assumptions name the access, volume, and turnaround the price depends on.", "The assumed list is the one most often missing. A provider may assume that the client supplies a working account, a complete brief, and an approver who responds within a day. When those assumptions fail, the service slows and the client blames the provider. Writing the assumptions turns a hidden dependency into a shared expectation.", "Keep the lists specific enough to test. A phrase such as general administrative support is not an inclusion because it does not name an output. A phrase such as draft and file the weekly customer report by Tuesday noon is testable. The catalog should use the second style wherever the work is recurring."]}, {"id": "response-and-review-promises", "heading": "Response and review promises", "paragraphs": ["Response time and review time are separate promises. A response time says when the assistant will acknowledge or begin, while a review time says when a person will approve the output. A catalog that promises a fast response but a slow review sets the client up for disappointment. Both clocks should be visible, with the starting event defined.", "The review model also affects the scope. If the client reviews every outbound message, the assistant's work ends at a draft. If the assistant sends against a written standard, the scope includes judgment and the risk that comes with it. The catalog should name the model and the sample used to check it. A client who expects sending but pays for drafting will dispute the first late reply.", "State the escalation path when a request falls outside the service. The client should know who to contact for a new task and how quickly the provider will respond. A named path prevents the assistant from improvising an exception at the edge of the scope. It also gives the provider a chance to price the work before it starts."]}, {"id": "change-control", "heading": "Change control for a living catalog", "paragraphs": ["A catalog that never changes becomes inaccurate within a quarter. New tools, new clients, and new requests shift the work. The provider needs a change process that names who can request a change, who approves it, and how the price and schedule adjust. The process should be short enough to use during a busy month.", "Version the catalog and record the effective date of each change. Tell the assistant which line changed and give one example of the new expectation. Keep the previous version for the current billing period so an invoice can be checked against the terms that applied. A quiet change creates the same dispute the catalog was meant to prevent.", "Review the catalog with the client on a fixed cadence, such as each quarter. Compare the promised service with the requests that actually arrived. Add the work that has become routine and remove the entries no one uses. The review keeps the document tied to the relationship rather than to the original sale."]}, {"id": "evidence-that-it-works", "heading": "Evidence that the catalog is working", "paragraphs": ["Track the number of requests that arrive outside the catalog and the time spent clarifying them. A falling count suggests that the client understands the service. A rising count may mean the catalog is hard to find or the request channel is unclear. The measure is a prompt for a conversation, not a score for the client.", "Track the disputes that reach an invoice and the reason for each. If most disputes concern the same entry, the entry is ambiguous. If they concern a category that is not in the catalog at all, the service has drifted. Use the pattern to revise one entry at a time rather than rewriting the whole document.", "Ask the assistant which request causes the most hesitation. Their answer often reveals a gap between the catalog and the real work. The assistant sees the request before the manager does and can describe the exact ambiguity. A catalog review that ignores that input will miss the entries that matter most.", "Compare the catalog with the actual invoice lines once a quarter. A service that appears on the invoice but not in the catalog, or the reverse, is a drift signal. Reconcile the two before the next billing cycle. The invoice and the catalog should describe the same service in the same words."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review draws on business guidance and a quality framework rather than a study of dispute rates. The sources support clear expectations and accurate promises, but they do not measure the effect of a catalog on a specific client relationship. The recommendations are a practical design method that a buyer can test. They are not a substitute for a contract review.", "A catalog also cannot resolve a disagreement about facts, such as whether a request was received or a deadline was met. Those questions need the queue, the timestamps, and the review record. The catalog defines the service, while the operating evidence proves what happened. A provider needs both to resolve a dispute fairly."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["List the recurring work in client language and name the output for each entry. Write the included, excluded, and assumed items separately. Define the response window, the review model, and the event that starts each clock. Publish the request channel and the fields a complete request needs.", "Set a change process with an owner, a notice period, and an effective date. Version the catalog and keep the prior version for the billing period. Review the entries with the client each quarter. Track out-of-catalog requests and invoice disputes, then revise one entry at a time."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-reliable-are-meeting-notes-as-a-record-of-decisions", "title": "How reliable are meeting notes as a record of decisions?", "description": "What a decision record needs, where notes drift from the discussion, and how to test a notes standard against real meetings.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/how-reliable-are-meeting-notes-as-a-record-of-decisions-hero.webp", "thumbnail": "/thumbnails/november-8/how-reliable-are-meeting-notes-as-a-record-of-decisions.webp", "heroAlt": "How reliable are meeting notes as a record of decisions?", "topic": "decision records", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/set-a-meeting-notes-standard-for-assistant-led-client-calls", "label": "Read the meeting notes standard guide"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "ISO 15489-1, Information and documentation, Records management", "href": "https://www.iso.org/standard/62542.html"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how reliable meeting notes are as a record of decisions. The unit is a note that a team relies on to show what was agreed and who owns the next step. The scope covers client and internal meetings where an assistant or coordinator takes the notes. The review does not address verbatim transcripts, legal depositions, or formal minutes governed by a specific statute or bylaws.", "The question matters because notes often become the only accessible record of a decision. A recording may be deleted, and the attendees may remember the conversation differently. If the note does not separate discussion from decision, a later reader can mistake a proposal for an agreement. The cost appears when a team builds on a commitment that was never made.", "The review treats reliability as a property of the record, not of the note-taker's memory. A reliable note identifies the decision, the owner, the date, and the basis. It also shows what remained open. A note that reads well but omits those elements is not reliable, even if it captures the general tone of the meeting."]}, {"id": "what-a-decision-record-needs", "heading": "What a decision record must contain", "paragraphs": ["A decision record needs the date, the attendees, the decision, the owner, and the next action. It should also state the condition or the evidence behind the decision when one exists. A reader who was not in the room should be able to understand what changed and what happens next. Those fields are the minimum for a record that can be used later.", "The record should distinguish a final decision from a recommendation, a proposal, or a topic for further review. A single word can change the meaning, so write the status explicitly. If the meeting produced no decision, say that and name the person who will decide. Silence in the notes is often read as agreement, which is the most common source of false commitments.", "National Archives records management guidance and ISO 15489 describe records as evidence of business activity that should be authentic, reliable, and usable. The standards are broader than meeting notes, but they support the same elements: who, what, when, and under what authority. A team can use them to explain why the note needs an owner and a retention rule. Quote the standard only for the principle, not as a legal opinion."]}, {"id": "discussion-versus-decision", "heading": "The gap between discussion and decision", "paragraphs": ["A meeting can spend most of its time exploring options and only a minute deciding. If the note gives equal weight to every option, the decision gets lost. Summarize the discussion only to the extent needed to explain the choice. Put the decision in its own field and write it as a complete sentence. The structure does the work that emphasis cannot.", "Notes also drift when the writer summarizes what they think the group meant rather than what was said. A facilitator who says we will look into it may be recorded as a commitment to deliver. The writer should use the speaker's words for a commitment and mark any interpretation. A short clarifying question during the meeting is cheaper than a correction later."]}, {"id": "attribution-and-owners", "heading": "Attribution and the owner problem", "paragraphs": ["An action without a named owner is a wish. The note should assign one accountable person, not a team or a department. If the owner is not in the room, the note should say who will confirm the assignment. A team label feels inclusive but hides the person who must act. The record should survive a change in team membership.", "Attribution also matters for decisions. A note that says the team agreed hides whether the client approved, the manager decided, or the group assumed consensus. Record the decision-maker and the basis, especially when the decision carries a cost or a risk. A later reader needs to know who had the authority.", "Dates should be as specific as the decision allows. A due date is different from a follow-up date, and a target is different from a commitment. Write the type of date beside the value. If the owner has not agreed to the date, mark it as proposed. A record that mixes the three creates false deadlines and unnecessary escalations.", "Name the person who confirmed the decision when the decision-maker is not the note-taker. A note that says it was agreed without a name invites a later dispute about authority. If the decision came from a written message after the meeting, attach or quote the message in the record. The note should point to the evidence, not replace it."]}, {"id": "retention-and-retrieval", "heading": "Retention and retrieval", "paragraphs": ["A note that cannot be found is not a record. Store the note in the client's approved system with a consistent name, such as the client, the date, and the meeting type. Add searchable fields for decisions and owners if the tool supports them. A folder structure alone will not help a reader who does not know where to look.", "Set a retention period that matches the client's recordkeeping duty and the sensitivity of the content. Remove notes that are past their period through an approved disposal method. Keep the restricted notes in a separate location with tighter access. The retention rule should cover both the note and any recording or attachment.", "NIST SP 800-53's audit and accountability controls support the idea that records need protection, review, and retention. The catalog is written for information systems rather than meeting files, but the principles apply to access and disposal. A team can use them to ask who may read a note and how long it stays. Apply the control in proportion to the sensitivity of the meeting."]}, {"id": "testing-the-standard", "heading": "Testing a notes standard on real meetings", "paragraphs": ["Test the standard on a sample of notes from the past month. Ask a reader who did not attend to identify the decision, the owner, and the date without opening the recording. Mark each note that requires a follow-up question. The count shows whether the template works, not whether the writer is careful.", "Compare the note with the attendees' memory for two or three meetings. Ask each attendee to state the decision independently, then compare the answers. A disagreement reveals a gap in how the decision was confirmed, not only how it was written. Update the call script so the facilitator reads the decision back before the meeting ends.", "Review the notes after a project milestone, when the team has to rely on them. Look for decisions that were recorded but never acted on and actions that were completed but never recorded. Both patterns show where the process breaks. A standard that is only tested at the end of the year will not catch the drift in time.", "Ask two reviewers to score the same sample against the template. If they disagree about whether a decision was recorded, the template is ambiguous. Clarify the field definitions before the next review. A standard that two trained readers cannot apply consistently will not survive a dispute."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review is based on records-management standards and a security control catalog rather than a measured study of note accuracy. The sources describe what a record should be, not how often a particular team gets it right. The testing method is a practical way to find gaps in a standard. It does not prove that a note is legally sufficient for a specific dispute.", "Notes also reflect the power dynamics of a meeting. A junior note-taker may soften a decision or omit a disagreement to avoid conflict. A standard should give the writer permission to record the decision plainly and a route to flag uncertainty. The reviewer should check for that pattern rather than blaming the writer for a structural problem."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Use a fixed template with attendees, decisions, actions, open questions, and the next date. Write each decision as a complete sentence and state its status. Name one accountable owner for every action and distinguish due dates from follow-up dates. Store the note in the approved system with a searchable name.", "Test a sample with a reader who did not attend. Compare two or three notes with the attendees' memory. Fix the template and the call script before coaching the writer. Set a retention and disposal rule. Recheck after any change to the template or the meeting process."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-share-of-expense-claims-arrive-without-usable-receipts", "title": "What share of expense claims arrive without usable receipts?", "description": "What makes a receipt usable, why claims arrive incomplete, and which controls improve first-pass completeness without slowing reimbursement.", "published": "2026-11-08", "readingMinutes": 8, "heroImage": "/hero/november-8/what-share-of-expense-claims-arrive-without-usable-receipts-hero.webp", "thumbnail": "/thumbnails/november-8/what-share-of-expense-claims-arrive-without-usable-receipts.webp", "heroAlt": "What share of expense claims arrive without usable receipts?", "topic": "expense evidence", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/run-a-weekly-expense-reconciliation-routine-for-a-support-assistant", "label": "Read the expense reconciliation guide"}, "sources": [{"label": "IRS Publication 463, Travel, Gift, and Car Expenses", "href": "https://www.irs.gov/publications/p463"}, {"label": "IRS, What kinds of records should I keep", "href": "https://www.irs.gov/businesses/small-businesses-self-employed/what-kinds-of-records-should-i-keep"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what share of expense claims arrive without a usable receipt and what a team can do about it. The unit is a claim submitted for reimbursement or client billing that lacks the documentation the reviewer needs. The scope covers routine business expenses handled by an assistant or a small operations team. The review does not estimate a universal rate, because the mix of card, cash, and mileage claims varies by organization and country.", "The question matters because a missing receipt creates work that is invisible in the original claim. The reviewer has to ask for it, the traveler has to find it, and the payment waits. A small number of incomplete claims can consume a disproportionate share of the weekly reconciliation time. The useful measure is not only the count but the delay each one causes.", "The review separates a missing receipt from an unusable one. A receipt can exist and still lack the merchant, the date, the amount, or the business purpose. A photo can be too blurry to read, or a card statement can show the charge without the detail. The claim is incomplete until the reviewer has enough to support the business purpose and the amount."]}, {"id": "what-counts-as-usable", "heading": "What counts as a usable receipt", "paragraphs": ["A usable receipt shows the merchant, the date, the amount, the currency, and the items or service purchased. It should be legible and complete enough to match the payment record. For a client-billable expense, it should also connect to the client or project. A receipt that shows only a total may be enough for a small claim and insufficient for a larger or disputed one.", "The IRS recordkeeping guidance for business expenses emphasizes supporting records that show the amount, the time, the place, and the business purpose. IRS Publication 463 applies the same idea to travel, meals, and gifts, with additional limits. These sources define a tax recordkeeping standard, not a universal company policy. A business may require more detail, but it should not require less than the law demands.", "The business purpose is often the weakest field. A receipt proves that a purchase happened, not why it was necessary. Ask the claimant to write one sentence that connects the expense to the work. A purpose such as client lunch to review the renewal is more useful than a label such as meals. The reviewer can then judge the claim against policy."]}, {"id": "why-claims-arrive-incomplete", "heading": "Why claims arrive incomplete", "paragraphs": ["The most common cause is timing. A receipt captured weeks later is harder to find, and the purpose is harder to recall. A traveler who is moving between meetings may photograph the receipt but never attach it to the claim. The gap is a process problem rather than a character flaw. A capture step at the point of purchase removes most of it.", "A second cause is a mismatch between the claim tool and the payment method. The card statement may show a merchant name that differs from the receipt, or a foreign transaction may post in a different currency. The claimant may not know which document the reviewer needs. Clear instructions and a worked example reduce the ambiguity.", "A third cause is the exception. A taxi driver who does not provide a receipt, a small vendor who writes a handwritten slip, or a cancelled flight with a credit rather than a refund all create a gap. The process needs a legitimate path for these cases. Without one, the claimant either gives up or invents a document, and both outcomes are worse than an exception."]}, {"id": "cost-of-rework", "heading": "The cost of rework and delayed reimbursement", "paragraphs": ["An incomplete claim triggers a message, a search, a reply, and a second review. The direct time may be small, but the delay can push the claim past a card due date or a client billing cycle. The reviewer also carries the claim in memory, which adds to the invisible workload. A weekly count of rework makes that cost visible.", "The claimant bears part of the cost through a delayed reimbursement or a personal cash flow gap. That experience shapes future behavior, and not always for the better. A traveler who waits a month for a legitimate claim may start avoiding small expenses or hoarding paper receipts. Neither response improves the record.", "Client billing adds another layer. An expense that cannot be supported may be disallowed or written off, which turns a documentation gap into a margin loss. The team may also spend time reconstructing the charge from emails and calendars. A first-pass completeness measure should include the client-billable claims separately, because the cost of a miss is higher."]}, {"id": "controls-that-improve-completeness", "heading": "Controls that improve first-pass completeness", "paragraphs": ["Move the capture step to the moment of purchase. Ask the traveler to photograph the receipt and add the business purpose before leaving the counter or the meeting. A mobile form with three fields is usually enough. The goal is to capture the two things that fade fastest, which are the paper and the reason.", "Match the claim to the card feed before the claimant submits it. A pre-filled claim with the merchant, date, and amount removes typing and catches a missing charge early. The claimant only adds the purpose and the client reference. This design reduces both the effort and the number of fields that can be left blank.", "Publish a short list of acceptable substitutes for a missing receipt, such as a bank record plus a written explanation, and name who approves them. Train the reviewer to apply the same standard every time. A substitute that is accepted for one claimant and rejected for another creates distrust and more exceptions. Keep the list short so it is easy to apply under pressure."]}, {"id": "the-legitimate-missing-receipt", "heading": "The legitimate missing receipt", "paragraphs": ["Some expenses genuinely lack a receipt. A small cash purchase, a tip, or a foreign vendor without a receipt printer may qualify. The process should require a written explanation and a secondary record, such as a card or bank line. The approver should see the substitute and the reason in one place. The exception should be rare and visible.", "Set a limit for receiptless claims and a separate approval for anything above it. Review the pattern monthly to see whether one traveler or one category produces most of the exceptions. A repeated exception is a sign that the process, not the person, needs a change. Adjust the intake or the payment method before adding more rules.", "Record the exception in the same system as the claim so the history is visible to the next reviewer. Do not keep a separate side list that only one person can find. Name the approver and the expiry of the exception. A substitute that is documented is easier to defend than one that is merely remembered.", "Review the approved exceptions at the end of the quarter and look for a category that has become common. A type of expense that repeatedly lacks a receipt may need a different payment method rather than a stricter rule. Change the method and measure the exception count again. The best control is the one that removes the need for the exception."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a measurement and control method rather than a study of claim completeness at a specific organization. The sources define recordkeeping expectations, not a benchmark rate. The actual share of incomplete claims depends on the payment mix, the tool, the culture, and the type of expense. A team should measure its own claims before setting a target.", "A completeness measure can also encourage behavior that looks good but hides risk. A claimant may attach a blurry photo to close the field, or a reviewer may accept a substitute to clear the queue. Sample the accepted claims, not only the rejected ones. The measure should reward a supportable claim rather than a complete-looking one."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define a usable receipt and a legitimate substitute in writing. Name the fields a complete claim needs, including the business purpose and the client reference. Put capture at the point of purchase and pre-fill from the card feed where possible. Set a limit and an approver for receiptless claims.", "Measure first-pass completeness and the delay caused by rework. Sample the accepted claims as well as the exceptions. Review the pattern by traveler, merchant, and category. Change one part of the process and compare the count next month."]}]}];
